	/* CSBKO of the MBC header */
	dmrgo_pdu_csbk_opcode_t opcode;
	/* reserved, 0 */
	uint8_t reserved1;
	/* color code of the destination channel */
	dmrgo_enums_color_code_t color_code;
	/* type of CdefParms, 0 for absolute frequencies */
	uint8_t cdeftype;
	/* reserved, 0 */
	uint8_t reserved2;
