struct dmrgo_dmrd_data_t {
	/* Seq is the sequence number of the packet in its stream; it wraps after 255. */
	uint8_t seq;
	/* Source is the radio ID of the caller (24 bits). */
	uint32_t source;
	/* Destination is the talkgroup or radio ID that is called (24 bits). */
	uint32_t destination;
	/* Repeater is the repeater ID, or for OpenBridge the network ID. */
	uint32_t repeater;
	/* Slot is the TDMA channel, DMRGO_ENUMS_SLOT1 or DMRGO_ENUMS_SLOT2. */
	dmrgo_enums_slot_t slot;
	/* Private reports a unit to unit call; false is a group call. */
	bool private_;
	/* Frame is the frame type. */
	dmrgo_dmrd_frame_type_t frame;
	/* Value is the data type of a DMRGO_DMRD_FRAME_DATA_SYNC packet, or the voice position N (0 to 5 for A to F) of a voice packet, as sent. */
	uint8_t value;
	/* Stream identifies the call. DMRGateway copies it in the byte order of its host, so treat it as opaque. */
	uint32_t stream;
	/* Burst is the 33-octet burst in transmit bit order. */
	dmrgo_layer2_raw_burst_t burst;
	/* BER is the bit error count that the repeater measured (55 and 71 octets). */
	uint8_t ber;
	/* RSSI is the received signal strength in dBm, as a positive number (55 and 71 octets). */
	uint8_t rssi;
	/* UUID is the trunking UUID of DMRGateway (71 octets). */
	uint8_t uuid[16];
	/* Size is the length of the packet: 53, 55 or 71, or 0 for 55, as MMDVMHost and DMRGateway send it. DMRGateway, HBlink4, DroidStar, xlxd and urfd drop a DMRD of 53 octets, and FreeDMR sends one on as a DMRE that its OpenBridge peers drop. */
	uint8_t size;
};

struct dmrgo_dmrd_bridge_t {
	/* Version is 1, 4 or 5: the 73, 85 or 89-octet form. */
	uint8_t version;
	/* Data is the DMRD packet. Its Size is 53 for version 1 and 55, with BER and RSSI, for versions 4 and 5. */
	dmrgo_dmrd_data_t data;
	/* Time is the send time in nanoseconds since 1970 (versions 4 and 5). */
	uint64_t time;
	/* SourceServer is the ID of the server that sent the call into OpenBridge (versions 4 and 5). */
	uint32_t source_server;
	/* SourceRepeater is the ID of the repeater that the call came from (version 5). */
	uint32_t source_repeater;
	/* Hops is the number of OpenBridge links the call has crossed (versions 4 and 5). */
	uint8_t hops;
	/* Signature is the HMAC-SHA1 signature of version 1, or in its first 16 octets the BLAKE2b hash of versions 4 and 5. */
	uint8_t signature[20];
};

struct dmrgo_dmrd_bridge_control_t {
	/* Command is DMRGO_DMRD_COMMAND_BCKA, DMRGO_DMRD_COMMAND_BCSQ, DMRGO_DMRD_COMMAND_BCST or DMRGO_DMRD_COMMAND_BCVE. */
	dmrgo_dmrd_command_t command;
	/* TalkGroup is the talkgroup of a BCSQ (24 bits). */
	uint32_t talk_group;
	/* Stream is the stream ID of a BCSQ. */
	uint32_t stream;
	/* Version is the version of a BCVE. */
	uint8_t version;
	/* Signature is the HMAC-SHA1 signature. */
	uint8_t signature[20];
};

struct dmrgo_dmrd_control_t {
	/* Command is the message. */
	dmrgo_dmrd_command_t command;
	/* ID is the repeater ID. In a DMRGO_DMRD_DIALECT_MMDVM RPTACK it is the 4 octets after the tag, which are the salt in the RPTACK that answers RPTL, as DMRGateway reads them; LoginSalt returns them. */
	uint32_t id;
	/* Salt is the salt of the acknowledgement that answers RPTL, with HasSalt: the DMRGO_DMRD_DIALECT_HBRP MSTACK in both directions, and the DMRGO_DMRD_DIALECT_MMDVM RPTACK for an encoder, which then writes Salt in place of ID. A decoder cannot tell that RPTACK from another one, so it leaves Salt zero there; use LoginSalt. */
	uint32_t salt;
	/* HasSalt reports whether Salt is set. */
	bool has_salt;
	/* Token is the login token of an RPTK (see package dmrdauth). */
	uint8_t token[32];
	/* Text is the rest of an RPTO (options), RPTG (home position), RPTRSSI or RPTINTR (slot and value) or DMRT (trunking command) message. A decode points it into the packet. */
	uint8_t *text;
	size_t text_len;
};

struct dmrgo_dmrd_option_value_t {
	/* State is whether the option is in the text. */
	dmrgo_dmrd_option_state_t state;
	/* Value is the number of a DMRGO_DMRD_OPTION_SET option. */
	uint32_t value;
};

struct dmrgo_dmrd_dmr_plus_options_t {
	/* StartRef is the default reflector of slot 2. */
	dmrgo_dmrd_option_value_t start_ref;
	/* RelinkTime is the time in minutes after which the repeater falls back to StartRef when there is no local traffic. */
	dmrgo_dmrd_option_value_t relink_time;
	/* UserLink is 1 when users may link to other reflectors, 0 when not. */
	dmrgo_dmrd_option_value_t user_link;
	/* TS1 holds the up to 5 static talkgroups of slot 1, TS1_1 to TS1_5. */
	dmrgo_dmrd_option_value_t ts1[5];
};

struct dmrgo_dmrd_local_position_t {
	/* Source is the radio ID (24 bits). */
	uint32_t source;
	/* Data is the 7 octets of the GPS Info LC after its FLCO and FID octets. */
	uint8_t data[7];
};

struct dmrgo_dmrd_local_talker_alias_t {
	/* Source is the radio ID of the talker (24 bits). */
	uint32_t source;
	/* Type is the talker alias block: 0 for the header, 1 to 3 for the blocks. */
	uint8_t type;
	/* Data is the 7 octets of the block, after its FLCO and FID octets. */
	uint8_t data[7];
};

struct dmrgo_dmrd_position_t {
	/* Repeater is the repeater ID. */
	uint32_t repeater;
	/* Source is the radio ID (24 bits). */
	uint32_t source;
	/* Data is the 7 octets of the GPS Info LC after its FLCO and FID octets (ETSI TS 102 361-2 clause 7.1.1.3). A 14-octet packet holds the first 3, and the others are 0. */
	uint8_t data[7];
	/* Size is the length of the packet: 14 or 18, or 0 for 14. */
	uint8_t size;
};

struct dmrgo_dmrd_talker_alias_t {
	/* Repeater is the repeater ID. */
	uint32_t repeater;
	/* Source is the radio ID of the talker (24 bits). */
	uint32_t source;
	/* Type is the talker alias block: 0 for the header, 1 to 3 for the blocks. */
	uint8_t type;
	/* Data is the 7 octets of the block, after its FLCO and FID octets (ETSI TS 102 361-2 clauses 7.1.1.4 and 7.1.1.5). A 15-octet packet holds the first 3, and the others are 0. */
	uint8_t data[7];
	/* Size is the length of the packet: 15 or 19, or 0 for 15. */
	uint8_t size;
};

struct dmrgo_dmrd_free_dmr_options_t {
	/* DialTS1 is the reflector that slot 1 links to: default_dial_ts1, DIAL1 or DEFAULT_DIAL_TS1. */
	dmrgo_dmrd_option_value_t dial_ts1;
	/* DialTS2 is the reflector that slot 2 links to: default_dial_ts2, DIAL2, DEFAULT_DIAL_TS2, DIAL, DEFAULT_REFLECTOR or the DMR+ StartRef. */
	dmrgo_dmrd_option_value_t dial_ts2;
	/* Timer is the time in minutes after which a talkgroup or reflector that a user linked drops: the DMR+ RelinkTime, TIMER or DEFAULT_UA_TIMER. 0 means no limit, here and in the other timers. */
	dmrgo_dmrd_option_value_t timer;
	/* TS1Timer is the timer of slot 1: TS1Timer or TS1_TIMER. */
	dmrgo_dmrd_option_value_t ts1_timer;
	/* TS2Timer is the timer of slot 2: TS2Timer or TS2_TIMER. */
	dmrgo_dmrd_option_value_t ts2_timer;
	/* TGTimer is the timer of talkgroups: TGTimer or TG_TIMER. */
	dmrgo_dmrd_option_value_t tg_timer;
	/* DialTimer is the timer of reflectors: DialTimer or DIAL_TIMER. */
	dmrgo_dmrd_option_value_t dial_timer;
	/* TS1TGTimer is the timer of talkgroups on slot 1: TGTO1 or TS1_TG_TIMER. */
	dmrgo_dmrd_option_value_t ts1tg_timer;
	/* TS2TGTimer is the timer of talkgroups on slot 2: TGTO2 or TS2_TG_TIMER. */
	dmrgo_dmrd_option_value_t ts2tg_timer;
	/* TS1DialTimer is the timer of reflectors on slot 1: DIALTO1 or TS1_DIAL_TIMER. */
	dmrgo_dmrd_option_value_t ts1_dial_timer;
	/* TS2DialTimer is the timer of reflectors on slot 2: DIALTO2 or TS2_DIAL_TIMER. */
	dmrgo_dmrd_option_value_t ts2_dial_timer;
	/* Voice is 1 when the master sends voice announcements, 0 when not: IDENT or VOICE. */
	dmrgo_dmrd_option_value_t voice;
	/* IdentTG is the talkgroup of the voice ident: IDENTTG, VOICETG or OVERRIDE_IDENT_TG. */
	dmrgo_dmrd_option_value_t ident_tg;
	/* Single is 1 for single mode, in which a slot carries one talkgroup at a time, 0 when not: SINGLE. */
	dmrgo_dmrd_option_value_t single;
	/* DialATG is 1 when users may link reflectors (dial-a-TG), 0 when not: DIALTG or DIAL_A_TG. */
	dmrgo_dmrd_option_value_t dial_atg;
	/* Dynamic is 1 when users may link talkgroups by calling them, 0 when not: DYNAMIC or DYNAMIC_TG_ROUTING. */
	dmrgo_dmrd_option_value_t dynamic;
	/* DirectDialSlot is the slot of network direct dial, 0, 1 or 2: NDD_SLOT or NETWORK_DIRECT_DIAL_SLOT. */
	dmrgo_dmrd_option_value_t direct_dial_slot;
	/* Key is the value of KEY, which FreeDMR compares with the key of the first options it accepted. It is a view of the text; empty means no key. */
	uint8_t *key;
	size_t key_len;
	/* Lang is the value of LANG, the language of the voice announcements, as a view of the text. */
	uint8_t *lang;
	size_t lang_len;
};

struct dmrgo_dmrd_hbrp_config_t {
	uint8_t v[306];
};

struct dmrgo_dmrd_mmdvm_config_t {
	uint8_t v[302];
};

struct dmrgo_dmrdsession_output_t {
	/* Kind is the kind of the output. */
	dmrgo_dmrdsession_output_kind_t kind;
	/* Packet is the packet of DMRGO_DMRDSESSION_OUTPUT_SEND, DMRGO_DMRDSESSION_OUTPUT_CONFIG, DMRGO_DMRDSESSION_OUTPUT_DATA and DMRGO_DMRDSESSION_OUTPUT_MESSAGE, or the options text of DMRGO_DMRDSESSION_OUTPUT_OPTIONS. It holds at most DMRGO_DMRDSESSION_MAX_PACKET octets. */
	uint8_t *packet;
	size_t packet_len;
	/* Command is the command of DMRGO_DMRDSESSION_OUTPUT_DATA and DMRGO_DMRDSESSION_OUTPUT_MESSAGE. */
	dmrgo_dmrd_command_t command;
	/* ID is the repeater ID of the session: a Master sets it in every output but DMRGO_DMRDSESSION_OUTPUT_SEND, a Peer only in DMRGO_DMRDSESSION_OUTPUT_UP, and a Bridge in none. */
	uint32_t id;
	/* Reason tells why for DMRGO_DMRDSESSION_OUTPUT_DOWN. */
	dmrgo_dmrdsession_reason_t reason;
	/* State is the state in which the session ended, for DMRGO_DMRDSESSION_OUTPUT_DOWN. */
	dmrgo_dmrdsession_state_t state;
};

struct dmrgo_dmrdsession_bridge_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Key is the passphrase of the OpenBridge link (see dmrgo_dmrdauth_new_bridge_key). */
	uint8_t *key;
	size_t key_len;
	/* Enhanced turns on FreeDMR's enhanced OpenBridge: the Bridge sends a BCKA every Keepalive and takes the peer as down after Timeout without a packet with a good signature. Without it OpenBridge has no keepalive, and the Bridge only checks signatures. */
	bool enhanced;
	/* Keepalive is the BCKA period. 0 means DMRGO_DMRDSESSION_KEEPALIVE_DEFAULT. */
	dmrgo_duration_t keepalive;
	/* Timeout is the time without a packet with a good signature after which an enhanced Bridge reports DMRGO_DMRDSESSION_OUTPUT_DOWN. 0 means DMRGO_DMRDSESSION_TIMEOUT_DEFAULT, the time after which FreeDMR stops sending to a peer. */
	dmrgo_duration_t timeout;
};

struct dmrgo_dmrdsession_master_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Dialect is DMRGO_DMRD_DIALECT_MMDVM or DMRGO_DMRD_DIALECT_HBRP. */
	dmrgo_dmrd_dialect_t dialect;
	/* Timeout is the time without a packet from the repeater after which the Master ends the session. 0 means DMRGO_DMRDSESSION_TIMEOUT_DEFAULT. */
	dmrgo_duration_t timeout;
	/* LoginTimeout is the time after the first RPTL of a login, and after the RPTK that proves the password, in which the repeater must finish its login, or the Master ends the session. A repeated RPTL does not restart it. 0 means DMRGO_DMRDSESSION_LOGIN_TIMEOUT_DEFAULT. */
	dmrgo_duration_t login_timeout;
};

struct dmrgo_dmrdsession_peer_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Dialect is DMRGO_DMRD_DIALECT_MMDVM or DMRGO_DMRD_DIALECT_HBRP. */
	dmrgo_dmrd_dialect_t dialect;
	/* ID is the repeater ID. */
	uint32_t id;
	/* Password is the password of the master. The Peer copies it. */
	uint8_t *password;
	size_t password_len;
	/* Config is the RPTC message: a dmrgo_dmrd_mmdvm_config_t (302 octets) for DMRGO_DMRD_DIALECT_MMDVM, a dmrgo_dmrd_hbrp_config_t (306 octets) for DMRGO_DMRD_DIALECT_HBRP. The Peer copies it. */
	uint8_t *config;
	size_t config_len;
	/* Options is the RPTO options text, at most DMRGO_DMRDSESSION_MAX_OPTIONS octets, which the Peer sends after the RPTC is acknowledged. Empty sends no RPTO. DMRGO_DMRD_DIALECT_HBRP has no RPTO. */
	uint8_t *options;
	size_t options_len;
	/* Retry is the time between two sends of a login step, between two pings, and before a new login after the session ended. 0 means DMRGO_DMRDSESSION_RETRY_DEFAULT. */
	dmrgo_duration_t retry;
	/* Timeout is the time without an acknowledgement or a pong after which the Peer ends the session and logs in again. 0 means DMRGO_DMRDSESSION_TIMEOUT_DEFAULT. */
	dmrgo_duration_t timeout;
	/* Backoff is the longest wait before a new login. Each session that ends before the login completes doubles the wait from Retry up to Backoff. 0, or a value up to Retry, waits Retry each time, as DMRGateway does. */
	dmrgo_duration_t backoff;
};

struct dmrgo_hytera_frame_t {
	/* Port is octets 0 and 1: 50002 (C3 52) on the bursts of the repeater in the DO1KBL capture, 0 on its sync packets, 5A 5A from others. */
	uint16_t port;
	/* Mark is octets 2 and 3: 00 50 or 00 00 in the DO1KBL capture, 5A 5A from others. */
	uint16_t mark;
	/* Seq is octet 4, one more for each packet; it wraps after 255. */
	uint8_t seq;
	/* PacketType is octet 8: 0x01 on bursts and 0x03 on terminators in the DO1KBL capture, 0x41 and 0x43 from others. */
	uint8_t packet_type;
	/* Slot is the TDMA channel, DMRGO_ENUMS_SLOT1 (1111) or DMRGO_ENUMS_SLOT2 (2222). */
	dmrgo_enums_slot_t slot;
	/* SlotType is what the burst is. */
	dmrgo_hytera_slot_type_t slot_type;
	/* ColorCode is octets 20 and 21, one nibble four times. */
	dmrgo_enums_color_code_t color_code;
	/* FrameType is octets 22 and 23: 0000 on bursts, 1111 or 6666 on sync packets. */
	uint16_t frame_type;
	/* Burst is the 33-octet burst in transmit bit order, with the octet pairs of the packet swapped back. A sync or wakeup packet carries no burst here. */
	dmrgo_layer2_raw_burst_t burst;
	/* Pad is octet 58, the octet after the burst in the payload. */
	uint8_t pad;
	/* CallType is octet 62: 0x01 for a group call and 0x00 for a private call from a Hytera repeater, 0x0A on wakeup packets. BrandMeister sends 0x00 on group calls too. Call and SetCall read and write it. */
	uint8_t call_type;
	/* Destination is the talkgroup or radio ID that is called (octets 64 to 66, little-endian). */
	uint32_t destination;
	/* Source is the radio ID of the caller (octets 68 to 70, little-endian). */
	uint32_t source;
	/* Reserved is octets 5 to 7, 9 to 15, 24 and 25, 60 and 61, 63, 67 and 71, in that order. */
	uint8_t reserved[17];
};

struct dmrgo_hytera_heartbeat_t {
	/* Keepalive reports the 1-octet keepalive. Only Code is then used. */
	bool keepalive;
	/* Code is octet 4: 0x0A on a heartbeat (0x0C is an acknowledgement in Hytera_Homebrew_Bridge), or the octet of a keepalive: 0x00 from a repeater, 0x41 from Hytera_Homebrew_Bridge. */
	uint8_t code;
	/* Seq is octet 12: 0x5A from the repeater and 0x5B in the reply of the master in the DO1KBL capture; Hytera_Homebrew_Bridge replies 0xFF. */
	uint8_t seq;
	/* Status is octets 13 to 15: 5A 59 5A, or 5A 01 5A from Hytera_Homebrew_Bridge. */
	uint8_t status[3];
	/* Reserved is octets 5 to 11 and 16 to 19: 00 00 00 14 00 00 00 and 00 00 00 00 in every capture. */
	uint8_t reserved[11];
};

struct dmrgo_hytera_p2p_t {
	/* Op is octet 3: 0x38 from the repeater, 0x50 from the master. */
	uint8_t op;
	/* Code is octet 4: 0x01 on a request, one more on its accept, 0x0B on a redirect, 0x0C on an acknowledgement. */
	uint8_t code;
	/* Seq is octet 12, a number that the repeater counts up for each request; an acknowledgement has the Seq of the redirect. */
	uint8_t seq;
	/* Status is octets 13 to 15: FF 11 02 or 01 11 02 on a request, 01 01 5A on an accept, FF 01 00 on a redirect, 01 59 5A on an acknowledgement. */
	uint8_t status[3];
	/* Reserved is octets 5 to 11 and 16 to 19: 00 00 00 14 00 00 00 and 00 00 00 00 in every capture. */
	uint8_t reserved[11];
	/* Body is the octets after octet 19: the service, 00 00 00, and then 01 on an accept or FF 01 and the port on a redirect. An acknowledgement has none. A decode points it into the packet. */
	uint8_t *body;
	size_t body_len;
};

struct dmrgo_ipsc_peer_entry_t {
	/* ID is the peer ID. */
	uint32_t id;
	/* IP is the IPv4 address of the peer. */
	uint8_t ip[4];
	/* Port is the UDP port of the peer. */
	uint16_t port;
	/* Mode is the mode of the peer. */
	dmrgo_ipsc_mode_t mode;
};

struct dmrgo_ipsc_flags_t {
	uint8_t v[4];
};

struct dmrgo_ipsc_control_t {
	/* Opcode is the packet. */
	dmrgo_ipsc_opcode_t opcode;
	/* ID is the peer or master ID of the sender. */
	uint32_t id;
	/* Mode is the mode of the sender (0x90, 0x91, 0x96 to 0x99). */
	dmrgo_ipsc_mode_t mode;
	/* Flags is the flags of the sender (0x90, 0x91, 0x96 to 0x99). */
	dmrgo_ipsc_flags_t flags;
	/* Peers is the number of peers in a DMRGO_IPSC_OP_REGISTER_REPLY. */
	uint16_t peers;
	/* ListLen is the length in octets of the peer list of a DMRGO_IPSC_OP_PEER_LIST_REPLY, 11 for each peer. */
	uint16_t list_len;
	/* Version is the protocol version (0x90, 0x91, 0x94 to 0x97). An XPR 8400 sends 04 08 04 00 in a register request and 04 02 04 01 in a keepalive request. */
	uint8_t version[4];
};

struct dmrgo_ipsc_raw_t {
	/* Opcode is the packet. */
	dmrgo_ipsc_opcode_t opcode;
	/* ID is octets 1 to 4, the sender ID. */
	uint32_t id;
	/* Body is the rest of the packet. A decode points it into the packet. */
	uint8_t *body;
	size_t body_len;
};

struct dmrgo_ipsc_rtp_t {
	/* Flags is octet 18: version 2, no padding, extension or CSRC (0x80). */
	uint8_t flags;
	/* Marker is the marker bit, set on the first voice header. */
	bool marker;
	/* PayloadType is 0x5D, or 0x5E on the last packet of a call. */
	uint8_t payload_type;
	/* Seq is the RTP sequence number, one more for each burst, lost ones included. */
	uint16_t seq;
	/* Timestamp is the RTP timestamp, 480 more for each burst. */
	uint32_t timestamp;
	/* SSRC is 0 on MOTOTRBO. */
	uint32_t ssrc;
};

struct dmrgo_ipsc_voice_t {
	/* Layout is the form of the packet: A, BCDF or E. */
	dmrgo_ipsc_voice_layout_t layout;
	/* Length is octet 31, the number of octets after it. */
	uint8_t length;
	/* Control is octet 32: 0x40 on burst A, 0x10 on burst E, and 0x01 when AMBE frame 1 was bad on receive. */
	uint8_t control;
	/* AMBE holds the three AMBE+2 frames without FEC (see dmrgo_vocoder_unpack_ambe_voice_flags). */
	uint8_t ambe[19];
	/* Embedded is the 32-bit embedded signalling field of bursts B to F. */
	uint8_t embedded[4];
	/* LC is the full LC of the call that burst E carries. */
	uint8_t lc[9];
	/* EMB is the EMB of bursts B to F without its FEC, as the repeater sent it. */
	dmrgo_pdu_emb_info_t emb;
};

struct dmrgo_ipsc_payload_t {
	/* Status is octet 31: bit 7 is slot 2, the rest are status bits. */
	uint8_t status;
	/* Words is octets 32 and 33, the number of 16-bit words after them. An XPR 8400 sends some DMRGO_IPSC_BURST_RAW packets with a Words 1 more than the packet holds, so it is kept as sent. */
	uint16_t words;
	/* HasBody reports whether octets 34 onward are present; a DMRGO_IPSC_BURST_SYNC_LOST packet has none. */
	bool has_body;
	/* Flags is octets 34 and 35: 0x80 in octet 34 means an RSSI follows, 0x08 in octet 35 a slot type, and 0x40 in octet 35 six octets of unknown meaning. */
	uint8_t flags[2];
	/* Bits is the payload size in bits: 96 for a BPTC burst, 144 for rate 3/4, 196 for DMRGO_IPSC_BURST_RAW. */
	uint16_t bits;
	/* Octets holds the payload, padded with zeros to whole 16-bit words: 12 octets for 96 bits, 18 for 144 and 26 for 196. */
	uint8_t octets[26];
	/* Trailer holds the octets after the payload, TrailerLen of them: the slot type, the unknown octets and the RSSI. */
	uint8_t trailer[16];
	/* TrailerLen is the number of octets in Trailer. */
	uint8_t trailer_len;
};

struct dmrgo_ipsc_user_t {
	/* Opcode is the packet. */
	dmrgo_ipsc_opcode_t opcode;
	/* ID is the peer ID of the sender. */
	uint32_t id;
	/* CallSeq is octet 5, the same in every packet of a call and one more for each call on an XPR 8400. */
	uint8_t call_seq;
	/* Source is the radio ID of the caller (24 bits). */
	uint32_t source;
	/* Destination is the talkgroup or radio ID (24 bits). */
	uint32_t destination;
	/* Priority is octet 12: 0x02 on voice and 0x01 on data on MOTOTRBO. */
	uint8_t priority;
	/* CallControl identifies the call. */
	uint32_t call_control;
	/* Info is octet 17: privacy, end and slot. */
	dmrgo_ipsc_call_info_t info;
	/* RTP is the RTP header. */
	dmrgo_ipsc_rtp_t rtp;
	/* Burst is octet 30. Compare dmrgo_ipsc_burst_type_type on dmrgo_ipsc_user_t.burst, which drops the slot 2 bit. */
	dmrgo_ipsc_burst_type_t burst;
	/* Voice is the burst of a voice packet. */
	dmrgo_ipsc_voice_t voice;
	/* Data is the burst of a data packet. */
	dmrgo_ipsc_payload_t data;
};

struct dmrgo_ipsc_stream_t {
	/* CallSeq is octet 5 of every packet of the call. An XPR 8400 counts it up by one for each call. */
	uint8_t call_seq;
	/* CallControl identifies the call in every packet. */
	uint32_t call_control;
	/* Seq is the RTP sequence number of the next packet. */
	uint16_t seq;
	/* Timestamp is the RTP timestamp of the next packet. */
	uint32_t timestamp;
	/* Sent is the number of packets that Fill has filled. */
	uint32_t sent;
};

struct dmrgo_ipscsession_addr_t {
	/* IP is the IPv4 address. */
	uint8_t ip[4];
	/* Port is the UDP port. */
	uint16_t port;
};

struct dmrgo_ipscsession_output_t {
	/* Kind is the kind of the output. */
	dmrgo_ipscsession_output_kind_t kind;
	/* Packet is the packet of DMRGO_IPSCSESSION_OUTPUT_SEND and DMRGO_IPSCSESSION_OUTPUT_DATA. It holds at most DMRGO_IPSCSESSION_MAX_PACKET octets. */
	uint8_t *packet;
	size_t packet_len;
	/* Addr is where to send DMRGO_IPSCSESSION_OUTPUT_SEND, and the address of the peer or master of every other output but DMRGO_IPSCSESSION_OUTPUT_PEERS. */
	dmrgo_ipscsession_addr_t addr;
	/* ID is the peer or master ID of DMRGO_IPSCSESSION_OUTPUT_UP, DMRGO_IPSCSESSION_OUTPUT_DOWN and DMRGO_IPSCSESSION_OUTPUT_DATA, and of DMRGO_IPSCSESSION_OUTPUT_DROPPED when the packet has one. */
	uint32_t id;
	/* Reason tells why for DMRGO_IPSCSESSION_OUTPUT_DOWN and DMRGO_IPSCSESSION_OUTPUT_DROPPED. */
	dmrgo_ipscsession_reason_t reason;
};

struct dmrgo_ipscsession_peer_info_t {
	/* ID is the peer ID. */
	uint32_t id;
	/* Addr is the address of the peer. */
	dmrgo_ipscsession_addr_t addr;
	/* Mode is the last mode of the peer. */
	dmrgo_ipsc_mode_t mode;
	/* Flags is the last flags of the peer, zero when not known. */
	dmrgo_ipsc_flags_t flags;
	/* Up reports whether the link with the peer is up. */
	bool up;
};

struct dmrgo_ipscsession_master_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* ID is the peer ID of the master. */
	uint32_t id;
	/* Mode is the mode that the master sends. 0 means DMRGO_IPSCSESSION_MODE_DEFAULT. */
	dmrgo_ipsc_mode_t mode;
	/* Flags is the flags that the master sends. The zero Flags means voice and data calls. The Master sets DMRGO_IPSC_FLAG_MASTER_PEER, and DMRGO_IPSC_FLAG_AUTH with Auth. */
	dmrgo_ipsc_flags_t flags;
	/* Auth turns on the HMAC-SHA1 trailer with Key: the Master drops a packet without a good trailer and signs what it sends. */
	bool auth;
	/* Key is the authentication key (see dmrgo_ipscauth_parse_key). */
	uint8_t key[20];
	/* Timeout is the time without a packet from a peer after which the Master drops it. 0 means DMRGO_IPSCSESSION_TIMEOUT_DEFAULT. */
	dmrgo_duration_t timeout;
	/* MaxPeers is the most peers that the Master registers. 0 means DMRGO_IPSCSESSION_MAX_PEERS_DEFAULT. */
	int64_t max_peers;
	/* AdoptKnown makes Packet adopt a peer that is not registered, as Adopt does, when the trailer of its packet proves the key of the config or the key that the caller passed, so that a peer that registered with another Master needs no Adopt call. Without a key it does nothing. */
	bool adopt_known;
	/* RegisterVersion is the protocol version that the master sends in a register request or reply (0x90, 0x91, 0x94, 0x95). Zero means RegisterVersionDefault. */
	uint8_t register_version[4];
	/* AliveVersion is the protocol version that the master sends in a keepalive request or reply (0x96, 0x97). Zero means AliveVersionDefault. */
	uint8_t alive_version[4];
};

struct dmrgo_ipscsession_peer_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* ID is the peer ID. */
	uint32_t id;
	/* Mode is the mode that the peer sends. 0 means DMRGO_IPSCSESSION_MODE_DEFAULT. */
	dmrgo_ipsc_mode_t mode;
	/* Flags is the flags that the peer sends. The zero Flags means voice and data calls. The Peer sets DMRGO_IPSC_FLAG_AUTH with Auth. */
	dmrgo_ipsc_flags_t flags;
	/* Master is the address of the master. */
	dmrgo_ipscsession_addr_t master;
	/* Auth turns on the HMAC-SHA1 trailer with Key: the Peer drops a packet without a good trailer and signs what it sends. */
	bool auth;
	/* Key is the authentication key (see dmrgo_ipscauth_parse_key). */
	uint8_t key[20];
	/* Alive is the keepalive period. 0 means DMRGO_IPSCSESSION_ALIVE_DEFAULT. */
	dmrgo_duration_t alive;
	/* MaxMissed is the number of keepalives without a reply after which the Peer takes a link as down. 0 means DMRGO_IPSCSESSION_MAX_MISSED_DEFAULT. */
	int64_t max_missed;
	/* MaxPeers is the most other peers that the Peer keeps from the peer list. 0 means DMRGO_IPSCSESSION_MAX_PEERS_DEFAULT. */
	int64_t max_peers;
	/* RegisterVersion is the protocol version that the peer sends in a register request or reply (0x90, 0x91, 0x94, 0x95). Zero means RegisterVersionDefault. */
	uint8_t register_version[4];
	/* AliveVersion is the protocol version that the peer sends in a keepalive request or reply (0x96, 0x97). Zero means AliveVersionDefault. */
	uint8_t alive_version[4];
};

