struct dmrgo_trunk_capacity_plus_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Plan, when set, maps the repeaters of the site to frequencies: channel number n is repeater n, which carries LSN 2n-1 on timeslot 1 and LSN 2n on timeslot 2. The Follower copies it and hunts over the repeaters that it names, in number order. Without a plan the Follower hunts nothing, and the consumer keeps the receiver on one repeater. */
	dmrgo_trunk_channel_plan_t *plan;
	/* Talkgroups holds the first TalkgroupsLen talkgroups to follow. TalkgroupsLen 0 follows every talkgroup. */
	uint32_t talkgroups[32];
	/* TalkgroupsLen is the number of entries of Talkgroups in use. */
	int64_t talkgroups_len;
	/* Individual follows private calls too: private voice grants, and the radio entries of a site status, which can also be data. */
	bool individual;
	/* NoFollow reports calls with DMRGO_TRUNK_OUTPUT_GRANT but never leaves the rest channel, for a receiver that cannot tune. */
	bool no_follow;
	/* NoSignal is the time without a valid Capacity Plus PDU on the rest channel after which the Follower hunts again, and the time it listens on each repeater while it hunts. 0 means DMRGO_TRUNK_CAPACITY_PLUS_NO_SIGNAL_DEFAULT, and a negative value turns the timer off. */
	dmrgo_duration_t no_signal;
	/* Inactive is the time without a burst of the call after which the Follower returns to the rest channel. 0 means DMRGO_CONSTANTS_TV_INACTIVE_DEFAULT, and a negative value turns the timer off. */
	dmrgo_duration_t inactive;
	/* Hangtime is the time after a Terminator with LC in which the Follower waits for more voice. 0 means DMRGO_CONSTANTS_TV_HANGTIME_DEFAULT, and a negative value turns the timer off. */
	dmrgo_duration_t hangtime;
	/* Scratch, when set, is the Burst that the Follower decodes into. NULL means the Follower makes its own. */
	dmrgo_layer2_burst_t *scratch;
};

struct dmrgo_trunk_tune_t {
	/* Channel is the channel number, or CHNULL for the TSCC that the consumer tuned last without a hunt list. */
	uint16_t channel;
	/* Slot is the TDMA channel to follow on a payload channel, or DMRGO_ENUMS_SLOT_UNKNOWN on a TSCC. */
	dmrgo_enums_slot_t slot;
	/* RXHz is the receive frequency from the channel plan or a CG_AP block, or 0 when not known. */
	uint64_t rx_hz;
	/* TXHz is the transmit frequency, or 0 when not known. */
	uint64_t tx_hz;
	/* ColorCode is the color code of the channel, when HasColorCode is set. */
	dmrgo_enums_color_code_t color_code;
	/* HasColorCode reports whether ColorCode is known. */
	bool has_color_code;
};

struct dmrgo_trunk_grant_t {
	/* Opcode is the CSBK opcode of the grant. */
	dmrgo_pdu_csbk_opcode_t opcode;
	/* Service is the service that the grant is for. */
	dmrgo_enums_service_kind_t service;
	/* Group reports whether Target is a talkgroup. */
	bool group;
	/* Target is the 24-bit talkgroup or MS address. */
	uint32_t target;
	/* Source is the 24-bit address of the calling MS. */
	uint32_t source;
	/* Channel is the payload channel, from the grant or its CG_AP block. */
	uint16_t channel;
	/* Slot is the TDMA channel of the call on the payload channel. */
	dmrgo_enums_slot_t slot;
	/* RXHz and TXHz are the frequencies of Channel from the plan or the CG_AP block, 0 when not known. */
	uint64_t rx_hz;
	/* RXHz and TXHz are the frequencies of Channel from the plan or the CG_AP block, 0 when not known. */
	uint64_t tx_hz;
	/* ColorCode is the color code from a CG_AP block, when HasColorCode is set. */
	dmrgo_enums_color_code_t color_code;
	/* HasColorCode reports whether ColorCode is known. */
	bool has_color_code;
	/* Emergency reports an emergency call. */
	bool emergency;
	/* LateEntry reports a grant sent again after the call set-up. */
	bool late_entry;
	/* Offset reports offset timing on the payload channel. */
	bool offset;
	/* HiRate reports dual slot data. */
	bool hi_rate;
};

struct dmrgo_trunk_output_t {
	/* Kind is the kind of the output. */
	dmrgo_trunk_output_kind_t kind;
	/* Tune is the channel of DMRGO_TRUNK_OUTPUT_TUNE. */
	dmrgo_trunk_tune_t tune;
	/* Grant is the grant of DMRGO_TRUNK_OUTPUT_GRANT and DMRGO_TRUNK_OUTPUT_CALL_END, and the call of DMRGO_TRUNK_OUTPUT_AHOY. */
	dmrgo_trunk_grant_t grant;
	/* Reason tells why for DMRGO_TRUNK_OUTPUT_LOST, DMRGO_TRUNK_OUTPUT_CALL_END and DMRGO_TRUNK_OUTPUT_REFUSED. */
	dmrgo_trunk_reason_t reason;
	/* Ack is the reason code of the TSCC for DMRGO_TRUNK_OUTPUT_REFUSED with DMRGO_TRUNK_REASON_NACK and for DMRGO_TRUNK_OUTPUT_REGISTERED. */
	dmrgo_enums_ack_reason_t ack;
	/* Burst is the burst of DMRGO_TRUNK_OUTPUT_BURST. */
	dmrgo_layer2_raw_burst_t burst;
	/* Hint is what Burst is, for a transport: its Slot and DMRGO_LAYER2_KIND_DATA with the data type of the burst. */
	dmrgo_layer2_hint_t hint;
	/* Slot is the TDMA channel of DMRGO_TRUNK_OUTPUT_BURST. */
	dmrgo_enums_slot_t slot;
	/* Due is the start of the inbound slot of DMRGO_TRUNK_OUTPUT_BURST, the time at which to transmit it. */
	dmrgo_duration_t due;
	/* Protect is the kind of DMRGO_TRUNK_OUTPUT_PROTECT. */
	dmrgo_enums_protect_kind_t protect;
	/* Challenge is the 24-bit challenge of DMRGO_TRUNK_OUTPUT_AUTH_CHALLENGE. */
	uint32_t challenge;
	/* Status is the status of DMRGO_TRUNK_OUTPUT_STATUS. */
	dmrgo_trunk_status_t status;
	/* Stun is the action of DMRGO_TRUNK_OUTPUT_STUN. */
	dmrgo_trunk_stun_action_t stun;
	/* RC is the command of DMRGO_TRUNK_OUTPUT_REVERSE_CHANNEL. */
	dmrgo_enums_rc_command_t rc;
};

struct dmrgo_trunk_channel_t {
	/* Number is the 12-bit channel number, 1 to 4094. */
	uint16_t number;
	/* RXHz is the frequency that the MS receives, the outbound channel of the BS. */
	uint64_t rx_hz;
	/* TXHz is the frequency that the MS transmits, the inbound channel of the BS. It is 0 for a receive-only plan. */
	uint64_t tx_hz;
};

struct dmrgo_trunk_channel_rule_t {
	/* First is the first channel number of the rule. */
	uint16_t first;
	/* Last is the last channel number of the rule, at least First. */
	uint16_t last;
	/* RXHz is the receive frequency of channel First. */
	uint64_t rx_hz;
	/* StepHz is the frequency step from one channel number to the next. */
	uint64_t step_hz;
	/* TXOffsetHz is the transmit frequency minus the receive frequency. */
	int64_t tx_offset_hz;
};

struct dmrgo_trunk_lip_short_report_t {
	/* PDU type, 0 for a short location report */
	uint8_t pdu_type;
	/* time since the position was found: 0 under 5 s, 1 under 5 min, 2 under 30 min, 3 unknown */
	uint8_t time_elapsed;
	/* degrees, -180 to 180 */
	double longitude;
	/* degrees, -90 to 90 */
	double latitude;
	/* position error */
	dmrgo_layer3_position_accuracy_t position_error;
	/* horizontal velocity code, 127 for unknown */
	uint8_t velocity;
	/* direction of travel in steps of 22.5 degrees, 0 is north */
	uint8_t direction;
	/* AdditionalData is user defined, false for the reason for sending */
	bool additional_type;
	/* reason for sending or user defined data */
	uint8_t additional_data;
};

struct dmrgo_trunk_usbd_lip_response_t {
	/* time since the position was found, as in LIPShortReport */
	uint8_t time_elapsed;
	/* degrees, -180 to 180 */
	double longitude;
	/* degrees, -90 to 90 */
	double latitude;
	/* position error */
	dmrgo_layer3_position_accuracy_t position_error;
	/* horizontal velocity code, 127 for unknown */
	uint8_t velocity;
	/* direction of travel in steps of 22.5 degrees */
	uint8_t direction;
	/* reason for sending, 0 for a response to an immediate request */
	uint8_t reason;
	/* 8-bit hash of the source address, as dmrgo_pdu_address_hash */
	uint8_t hashed_source;
};

struct dmrgo_trunk_usbd_poll_request_t {
	/* RD: the poll response is due 1 to 4 TDMA frames later */
	uint8_t response_delay;
	/* PC: Parameters holds data */
	bool payload_contents;
	/* reserved, false */
	bool reserved;
	/* 48 bits that depend on the Service Type */
	uint64_t parameters;
	/* MS target address */
	uint32_t target;
};

struct dmrgo_trunk_dynamic_groups_t {
	/* Groups holds ADDRESS1 to ADDRESS15 of the DGNA_Address mode in its first 15 entries and the talkgroup of the DGNA_Alias mode in the last. DMRGO_CONSTANTS_ADDRESS_NULL marks an unused entry. */
	uint32_t groups[16];
	/* OneKey is the One-key_talkgroup, when HasOneKey is set. */
	uint32_t one_key;
	/* HasOneKey reports whether the MS holds a One-key_talkgroup. */
	bool has_one_key;
};

struct dmrgo_trunk_neighbor_t {
	/* SysCode14 is the 14 most significant bits of the C_SYScode of the adjacent TSCC, as dmrgo_pdu_sys_code_unpack14 takes them. */
	uint16_t sys_code14;
	/* Channel is the channel number of the adjacent TSCC. */
	uint16_t channel;
	/* HasActiveConn reports whether ActiveConn is known. */
	bool has_active_conn;
	/* ActiveConn reports whether the adjacent site has a network connection. */
	bool active_conn;
	/* ConfirmedPriority is the priority of the confirmed channel. */
	uint8_t confirmed_priority;
	/* AdjacentPriority is the priority of the adjacent channel. */
	uint8_t adjacent_priority;
};

struct dmrgo_trunk_site_t {
	/* SysCode is the C_SYScode of the TSCC. Par is set only when a C_ALOHA or C_BCAST gave the whole 16 bits. */
	dmrgo_pdu_sys_code_t sys_code;
	/* HasSysCode reports whether SysCode is known. */
	bool has_sys_code;
	/* ColorCode is the color code of the TSCC. */
	dmrgo_enums_color_code_t color_code;
	/* Channel is the channel number of the TSCC, or CHNULL when the consumer tuned to it without a hunt list. */
	uint16_t channel;
	/* Reg reports whether the TSCC requires MSs to register. */
	bool reg;
	/* Version is the version of ETSI TS 102 361-4 that the system follows, from C_ALOHA. */
	uint8_t version;
	/* Offset reports whether the TSCC uses offset timing. */
	bool offset;
	/* ActiveConn reports whether the site has a network connection. */
	bool active_conn;
	/* SiteTSSync reports whether all channels of the site are timeslot synchronized. */
	bool site_ts_sync;
	/* Access is the random access control of the last C_ALOHA. HasAccess reports whether one arrived. */
	dmrgo_trunk_access_t access;
	/* HasAccess reports whether Access holds a C_ALOHA. */
	bool has_access;
	/* SlotCounter is the Common_Slot_Counter of the last C_SYS_Parms, which counts 120 ms steps modulo 512 (ETSI TS 102 361-4 clause 5.1.3). */
	uint16_t slot_counter;
	/* Neighbors holds the first NeighborsLen adjacent sites announced. */
	dmrgo_trunk_neighbor_t neighbors[8];
	/* NeighborsLen is the number of entries of Neighbors in use. */
	int64_t neighbors_len;
};

struct dmrgo_trunk_udt_t {
	/* Header is the C_UDTHD header. Its UAB plus one is the number of appended blocks. */
	dmrgo_pdu_udt_header_t header;
	/* Data holds the 12*(dmrgo_trunk_udt_t.header.uab+1)-2 octets of the appended blocks before the CRC of the last block. */
	uint8_t data[46];
	/* CRCOK reports whether the CRC of the last block checks. */
	bool crc_ok;
};

struct dmrgo_trunk_follower_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* SysCode, when set, is the system to follow: a TSCC with another MODEL, NET or SITE is skipped. has_sys_code false follows the first TSCC found. */
	bool has_sys_code;
	dmrgo_pdu_sys_code_t sys_code;
	/* Hunt, when set, is the hunt list. The Follower copies it, asks for each channel in turn with DMRGO_TRUNK_OUTPUT_TUNE until it finds a TSCC, and adds and withdraws channels on an Ann_WD_TSCC broadcast. With a NULL or empty Hunt the consumer keeps the receiver on one TSCC, which is then channel CHNULL. */
	dmrgo_trunk_hunt_list_t *hunt;
	/* Plan, when set, is the channel plan to start from. The Follower copies it and adds the channels that CG_AP and Chan_Freq announce. */
	dmrgo_trunk_channel_plan_t *plan;
	/* Talkgroups holds the first TalkgroupsLen 24-bit talkgroups to follow. TalkgroupsLen 0 follows every talkgroup. */
	uint32_t talkgroups[32];
	/* TalkgroupsLen is the number of entries of Talkgroups in use. */
	int64_t talkgroups_len;
	/* Individual follows individual voice calls too. */
	bool individual;
	/* Data follows packet data grants too. */
	bool data;
	/* NoFollow reports grants with DMRGO_TRUNK_OUTPUT_GRANT but never leaves the TSCC, for a receiver that cannot tune, such as the replay of a recording. */
	bool no_follow;
	/* NoSignal is T_Nosig, the time without a TSCC burst after which the Follower hunts again, and the time it listens on each hunt list channel. 0 means DMRGO_CONSTANTS_T_NO_SIGNAL_DEFAULT, and a negative value turns the timer off (ETSI TS 102 361-4 Table A.1). */
	dmrgo_duration_t no_signal;
	/* Inactive is TV_Inactive, the time without a burst on the payload channel after which the Follower returns to the TSCC. 0 means DMRGO_CONSTANTS_TV_INACTIVE_DEFAULT, and a negative value turns the timer off. */
	dmrgo_duration_t inactive;
	/* Hangtime is the time after a Terminator with LC in which the Follower waits on the payload channel for more voice. 0 means DMRGO_CONSTANTS_TV_HANGTIME_DEFAULT, and a negative value turns the timer off. */
	dmrgo_duration_t hangtime;
	/* SysErrors is NSYSerr, the number of C_SYScodes from another system after which the Follower leaves the TSCC. 0 means DMRGO_CONSTANTS_N_SYS_ERR_DEFAULT; a negative value is an error. */
	int64_t sys_errors;
	/* AcceptRAS takes a CSBK whose CRC fails as valid when its BPTC needed no correction and its BPTC reserved bit R(2) flags RAS. The CRC of a Motorola Capacity Max system with RAS is a MAC with the key of the system, which the Follower cannot check. */
	bool accept_ras;
	/* Scratch, when set, is the Burst that the Follower decodes into, as for dmrgo_voice_receiver_config_t.scratch. NULL means the Follower makes its own. */
	dmrgo_layer2_burst_t *scratch;
};

struct dmrgo_trunk_hunt_entry_t {
	/* Channel is the channel number. */
	uint16_t channel;
	/* ColorCode is the color code of the TSCC on the channel, when HasColorCode is set. */
	dmrgo_enums_color_code_t color_code;
	/* HasColorCode reports whether ColorCode is known. */
	bool has_color_code;
};

struct dmrgo_trunk_ms_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Address is the 24-bit individual address of the MS, 1 to 0xFFFCDF. */
	uint32_t address;
	/* Talkgroups holds the first TalkgroupsLen 24-bit talkgroups whose calls the MS follows and whose radio checks it answers. Its own calls and the individual calls to it are always followed. */
	uint32_t talkgroups[32];
	/* TalkgroupsLen is the number of entries of Talkgroups in use. */
	int64_t talkgroups_len;
	/* SysCode, when set, is the system to use, as in FollowerConfig. */
	bool has_sys_code;
	dmrgo_pdu_sys_code_t sys_code;
	/* Hunt, when set, is the hunt list, as in FollowerConfig. */
	dmrgo_trunk_hunt_list_t *hunt;
	/* Plan, when set, is the channel plan to start from. */
	dmrgo_trunk_channel_plan_t *plan;
	/* Slot is the TDMA channel of the TSCC on which the MS makes random access. DMRGO_ENUMS_SLOT_UNKNOWN means DMRGO_ENUMS_SLOT1. */
	dmrgo_enums_slot_t slot;
	/* Seed seeds the random choice of the backoff frames. Two MSs with the same seed make the same choices; 0 is a valid seed. */
	uint64_t seed;
	/* NoRegistration keeps the MS from registering when the TSCC asks for it with Reg. */
	bool no_registration;
	/* RandomTimeout is TRand_TC, the longest time of a random access. 0 means DMRGO_CONSTANTS_T_RAND_TC_DEFAULT, and a negative value turns the timer off. (ETSI TS 102 361-4 clause 6.2.1.1.7) */
	dmrgo_duration_t random_timeout;
	/* CallTimeout is TP_Timer, the longest wait for the grant of a service that needs a payload channel. 0 means DMRGO_CONSTANTS_TP_TIMER_DEFAULT, and a negative value turns the timer off. */
	dmrgo_duration_t call_timeout;
	/* RegTimeout is TNP_Timer, the longest wait for the answer to a registration after an intermediate acknowledgement. 0 means DMRGO_CONSTANTS_TNP_TIMER_DEFAULT, and a negative value turns the timer off. */
	dmrgo_duration_t reg_timeout;
	/* Pending is T_Pending, the time a called MS waits for the grant after it accepted a C_AHOY. 0 means DMRGO_CONSTANTS_T_PENDING_DEFAULT. */
	dmrgo_duration_t pending;
	/* Dereg is T_Dereg, the longest wait for the answer to a de-registration. 0 means DMRGO_CONSTANTS_T_DEREG_DEFAULT. */
	dmrgo_duration_t dereg;
	/* DeniedLife is T_DENREG, how long a Reg_Denied keeps the MS off a SYS_AREA. 0 means DMRGO_CONSTANTS_T_DEN_REG_DEFAULT, and a negative value keeps the entry until Reset. */
	dmrgo_duration_t denied_life;
	/* DMRLA is the number of most significant SITE bits in the SYS_AREA of the registration and denied records. 0 means DMRGO_CONSTANTS_DMRLA_DEFAULT. */
	int64_t dmrla;
	/* MinLevelHunt, when set, is the signal level below which the MS does not confirm a TSCC, as L_Lower_SHort, in the unit of the levels that the consumer passes to Quality. */
	bool has_min_level_hunt;
	int64_t min_level_hunt;
	/* MinLevelIdle, when set, is the signal level below which the MS leaves a confirmed TSCC, in the unit of MinLevelHunt. */
	bool has_min_level_idle;
	int64_t min_level_idle;
	/* MaxBERPermille is the bit error rate of the TSCC above which the MS leaves it. 0 means DMRGO_TRUNK_DEFAULT_MAX_BER_PERMILLE, and a negative value turns the check off. */
	int64_t max_ber_permille;
	/* AcceptRAS is as in FollowerConfig. */
	bool accept_ras;
	/* NoSignal is T_Nosig, as in FollowerConfig. */
	dmrgo_duration_t no_signal;
	/* Inactive is TV_Inactive, as in FollowerConfig. */
	dmrgo_duration_t inactive;
	/* Hangtime is the payload hang time, as in FollowerConfig. */
	dmrgo_duration_t hangtime;
	/* Scratch is the decode Burst, as in FollowerConfig. */
	dmrgo_layer2_burst_t *scratch;
	/* NoDuplex refuses full-duplex calls to the MS with MS_Duplex_Not_Supported. */
	bool no_duplex;
	/* Ambient accepts Ambient Listening Service calls to the MS. Without it the MS refuses them with MSNot_Supported. */
	bool ambient;
	/* Auth, when set, makes the MS authenticate the TSCC before a stun or revive, and lets it accept a kill, which is always authenticated. Without it the MS refuses a kill as not supported. The MS keeps Auth and does not copy what it points to, such as a *dmrgo_trunkauth_key_t or a *dmrgo_trunkauth_keys_t and its Entries. Do not change it while the MS uses it. (ETSI TS 102 361-4 clauses 6.4.9.2 and 6.4.10) */
	dmrgo_trunk_authenticator_t *auth;
	/* NoStun makes the MS refuse a stun or revive as not supported. */
	bool no_stun;
	/* NoKill makes the MS refuse a kill as not supported. */
	bool no_kill;
	/* Stunned starts the MS stunned, for an MS that a TSCC stunned before. */
	bool stunned;
	/* Killed starts the MS killed, for an MS that a TSCC killed before. */
	bool killed;
	/* PowerSave is the PowerSave_RQ of the registrations of the MS, 0 to 7: the MS asks to be awake for one power save frame in 2^PowerSave. 0 asks for no power save. (ETSI TS 102 361-4 clause 6.4.7) */
	uint8_t power_save;
	/* Awake is T_Awake, the time the MS stays awake after a PDU for it in power save. 0 means DMRGO_CONSTANTS_T_AWAKE_DEFAULT. */
	dmrgo_duration_t awake;
};

struct dmrgo_trunk_tscc_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* SysCode is the C_SYScode of the site. */
	dmrgo_pdu_sys_code_t sys_code;
	/* ColorCode is the color code of the TSCC and its payload channels. */
	dmrgo_enums_color_code_t color_code;
	/* Channel is the channel number of the TSCC, for the outputs of its carrier: 1 to 0xFFE. */
	uint16_t channel;
	/* Payload holds the first PayloadLen channel numbers of the payload channels, each 1 to 0xFFE, different from each other and from Channel. Each has two slots for calls. */
	uint16_t payload[16];
	/* PayloadLen is the number of entries of Payload in use, 1 or more. */
	int64_t payload_len;
	/* Reg asks MSs to register, and refuses the services of an MS that is not registered. */
	bool reg;
	/* MaxRegistrations is the size of the registration table, at most 65536. 0 means 64. */
	int64_t max_registrations;
	/* NRandWait is the NRand_Wait of C_ALOHA. 0 means the code of DMRGO_CONSTANTS_N_DEFAULT_NW. */
	dmrgo_enums_n_rand_wait_t n_rand_wait;
	/* Backoff is the backoff number of C_ALOHA. 0 means 3. */
	dmrgo_enums_backoff_t backoff;
	/* GrantRepeats is the number of times the TSCC sends a grant. 0 means 2; a negative value is an error. */
	int64_t grant_repeats;
	/* ClearRepeats is the number of times the TSCC sends P_CLEAR. 0 means 3; a negative value is an error. */
	int64_t clear_repeats;
	/* LateEntry is the time between the late entry grants of a call. 0 means 1 s, and a negative value sends none. */
	dmrgo_duration_t late_entry;
	/* Hangtime is TV_Hangtime, the time after the end of a transmission in which the call keeps its payload slot. 0 or a negative value means DMRGO_CONSTANTS_TV_HANGTIME_DEFAULT. */
	dmrgo_duration_t hangtime;
	/* Inactive is TV_Inactive, the time without an inbound burst after which the TSCC clears a call that never started. 0 or a negative value means DMRGO_CONSTANTS_TV_INACTIVE_DEFAULT. */
	dmrgo_duration_t inactive;
	/* AnswerTimeout is how long the TSCC waits for the answer of a called MS to its C_AHOY, and for the answer to an authentication challenge. 0 or a negative value means DMRGO_CONSTANTS_TP_TIMER_DEFAULT. */
	dmrgo_duration_t answer_timeout;
	/* Authenticate challenges each MS that registers with a C_AHOY, and registers it only when its answer matches the response that the consumer passes to ExpectAuth after DMRGO_TRUNK_TSCC_AUTH_CHALLENGE. A wrong answer gets C_NACKD Reg_Denied, and no answer within AnswerTimeout gets C_NACKD Reg_Refused. */
	bool authenticate;
	/* Seed seeds the random choice of the authentication challenges. */
	uint64_t seed;
	/* Auth, when set, answers the authentication challenge of an MS before a stun, revive or kill. The TSCC keeps Auth and does not copy what it points to, such as a *dmrgo_trunkauth_keys_t and its Entries. Do not change it while the TSCC uses it. (ETSI TS 102 361-4 clauses 6.4.9.2 and 6.4.10) */
	dmrgo_trunk_authenticator_t *auth;
	/* TransmitInterrupt accepts the transmit interrupt requests of MSs, status calls with DMRGO_TRUNK_STATUS_INTERRUPT and DMRGO_TRUNK_STATUS_TERMINATE. (ETSI TS 102 361-4 clause 6.4.14.3) */
	bool transmit_interrupt;
	/* MaxCall is the longest time of a call. At its end the TSCC stops the transmission with the reverse channel and clears the call. 0 or a negative value means no limit. (ETSI TS 102 361-4 clause 6.4.14.3.2) */
	dmrgo_duration_t max_call;
	/* PowerSave gives the MSs that ask for it a power save frame, and holds the C_AHOY to an MS that sleeps until its frame. (ETSI TS 102 361-4 clause 6.4.7) */
	bool power_save;
	/* Awake is T_Awake, as in MSConfig. 0 or a negative value means DMRGO_CONSTANTS_T_AWAKE_DEFAULT. */
	dmrgo_duration_t awake;
	/* IP offers the IP bearer service: the TSCC takes the IP connection advice of MSs. Without it the TSCC refuses the advice with IP_Connection_failed. (ETSI TS 102 361-4 clause 6.4.11) */
	bool ip;
	/* Supplementary takes the supplementary_user data of call requests and passes it to the called party before the call. Without it the TSCC sets up the call without the data. (ETSI TS 102 361-4 clause 6.4.13) */
	bool supplementary;
	/* Lead makes Tick emit the bursts of a slot this long before its Due time, so that an RF FIFO can be filled ahead. 0 means at Due; it must be at least 0 and less than DMRGO_TRUNK_MAX_LEAD. The timers of the TSCC keep to the Due times. */
	dmrgo_duration_t lead;
};

struct dmrgo_trunk_tscc_output_t {
	/* Kind is the kind of the output. */
	dmrgo_trunk_tscc_output_kind_t kind;
	/* Channel is the channel number of the carrier of DMRGO_TRUNK_TSCC_BURST. */
	uint16_t channel;
	/* Slot is the TDMA channel of DMRGO_TRUNK_TSCC_BURST. */
	dmrgo_enums_slot_t slot;
	/* CACH is the CACH before the burst of DMRGO_TRUNK_TSCC_BURST, in transmit order. */
	uint8_t cach[3];
	/* Burst is the burst of DMRGO_TRUNK_TSCC_BURST. */
	dmrgo_layer2_raw_burst_t burst;
	/* Due is the start of the 30 ms slot of DMRGO_TRUNK_TSCC_BURST, the time at which it goes on air. */
	dmrgo_duration_t due;
	/* Hint is what Burst is, for a transport: Slot, and DMRGO_LAYER2_KIND_DATA with the data type, or for a relayed burst what the TSCC decoded of it: the kind, the data type, and voice burst A from its SYNC. */
	dmrgo_layer2_hint_t hint;
	/* Address is the MS of DMRGO_TRUNK_TSCC_REGISTERED, DMRGO_TRUNK_TSCC_DEREGISTERED, DMRGO_TRUNK_TSCC_REFUSED, DMRGO_TRUNK_TSCC_DELIVERED, DMRGO_TRUNK_TSCC_UDT, DMRGO_TRUNK_TSCC_DIVERSION, DMRGO_TRUNK_TSCC_STUN, DMRGO_TRUNK_TSCC_INTERRUPT and DMRGO_TRUNK_TSCC_IP_ADVICE. */
	uint32_t address;
	/* Ack is the reason of DMRGO_TRUNK_TSCC_REFUSED and DMRGO_TRUNK_TSCC_DELIVERED, and the answer of the MS for DMRGO_TRUNK_TSCC_STATUS and DMRGO_TRUNK_TSCC_STUN. */
	dmrgo_enums_ack_reason_t ack;
	/* Grant is the call of DMRGO_TRUNK_TSCC_CALL_START, DMRGO_TRUNK_TSCC_CALL_END and DMRGO_TRUNK_TSCC_INTERRUPT, and the parties of DMRGO_TRUNK_TSCC_STATUS. */
	dmrgo_trunk_grant_t grant;
	/* Reason tells why for DMRGO_TRUNK_TSCC_CALL_END, DMRGO_TRUNK_TSCC_STATUS, DMRGO_TRUNK_TSCC_STUN and DMRGO_TRUNK_TSCC_INTERRUPT. */
	dmrgo_trunk_reason_t reason;
	/* Challenge is the 24-bit challenge of DMRGO_TRUNK_TSCC_AUTH_CHALLENGE. */
	uint32_t challenge;
	/* Status is the status of DMRGO_TRUNK_TSCC_STATUS. */
	dmrgo_trunk_status_t status;
	/* Stun is the action of DMRGO_TRUNK_TSCC_STUN. */
	dmrgo_trunk_stun_action_t stun;
	/* IP holds the IPv4 address of DMRGO_TRUNK_TSCC_IP_ADVICE in its first 4 octets, or the IPv6 address when IPv6 is set. */
	uint8_t ip[16];
	/* IPv6 reports an IPv6 address in IP. */
	bool ipv6;
	/* Remove reports that the MS removes the address, rather than adds it. */
	bool remove;
};

struct dmrgo_trunkauth_key_t {
	/* K is the authentication key of the MS. */
	uint8_t k[16];
	/* PSN is the PSN of the MS, or 0 for an MS that uses no PSN. */
	uint32_t psn;
};

struct dmrgo_trunkauth_entry_t {
	/* Addr is the individual address of the MS. */
	uint32_t addr;
	/* Key is the key of the MS. */
	dmrgo_trunkauth_key_t key;
};

struct dmrgo_vocoder_codec_vtable_t {
	/* size is sizeof the struct, which the caller sets. A method that it does not cover, or whose function is NULL, fails with DMRGO_ERR_NO_METHOD, or gives zero results when it has no error. A function that returns an error gives zero results. */
	size_t size;
	DMRGO_USER_T user;
	int (*close)(DMRGO_USER_T user);
	/* Decode decodes one 72-bit frame, appends its FrameSamples samples to dst and returns the extended slice. */
	int (*decode)(DMRGO_USER_T user, int16_t *dst, size_t dst_cap, size_t *dst_len, size_t *dst_need, const uint8_t slot[9]);
	/* Encode encodes exactly FrameSamples samples into one 72-bit frame. */
	int (*encode)(DMRGO_USER_T user, const int16_t *pcm, size_t pcm_len, uint8_t out[9]);
	/* FID returns the Feature set ID to send in the Full LC of calls that use this codec. */
	int (*fid)(DMRGO_USER_T user, dmrgo_enums_fid_t *out);
	/* FrameSamples returns the number of PCM samples in one frame. */
	int (*frame_samples)(DMRGO_USER_T user, int64_t *out);
	/* Silence returns a frame that decodes to silence, for padding the last burst of a call. */
	int (*silence)(DMRGO_USER_T user, uint8_t out[9]);
	/* Reset starts a new call: the decoder drops what it learned from the frames of the call before, such as a detected mode. */
	int (*reset)(DMRGO_USER_T user);
};

struct dmrgo_codec2_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Mode is the Codec2 bit rate. Zero is DMRGO_CODEC2_MODE_AUTO: the decoder detects DMRGO_CODEC2_MODE2400 or DMRGO_CODEC2_MODE3200 from the padding of the frames of each call, and the encoder uses DMRGO_CODEC2_MODE2400. */
	dmrgo_codec2_mode_t mode;
	/* FID is the Feature set ID to send in the Full LC. Zero selects DMRGO_CODEC2_DEFAULT_FID. FID 0 is the ETSI feature set, which repeaters treat as AMBE, so it cannot be selected. */
	dmrgo_enums_fid_t fid;
};

struct dmrgo_dvsi_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Channel is the vocoder channel of the chip, 0 to DMRGO_DVSI_MAX_CHANNEL. The AMBE-3000R has only channel 0. */
	int64_t channel;
	/* Timeout is the longest wait for each reply. Zero selects DMRGO_DVSI_DEFAULT_TIMEOUT. */
	dmrgo_duration_t timeout;
	/* NoReset leaves out the reset of the chip, for a second Codec on another channel of an AMBE-3003 that is already in use. */
	bool no_reset;
	/* NoParity turns the parity fields off. By default every packet carries a parity field and the chip drops packets with a wrong parity byte. */
	bool no_parity;
};

struct dmrgo_dvsi_packet_t {
	/* Type is the packet type. */
	dmrgo_dvsi_packet_type_t type;
	/* Fields holds the bytes after the header, without the parity field. It points into the bytes given to Parse. */
	uint8_t *fields;
	size_t fields_len;
};

struct dmrgo_dvsi_port_vtable_t {
	/* size is sizeof the struct, which the caller sets. A method that it does not cover, or whose function is NULL, fails with DMRGO_ERR_NO_METHOD, or gives zero results when it has no error. A function that returns an error gives zero results. */
	size_t size;
	DMRGO_USER_T user;
	/* Read reads bytes from the chip into p. */
	int (*read)(DMRGO_USER_T user, uint8_t *p, size_t p_len, int64_t *out);
	/* Write writes the bytes of p to the chip. */
	int (*write)(DMRGO_USER_T user, const uint8_t *p, size_t p_len, int64_t *out);
};

struct dmrgo_voice_call_options_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* PIHeader, when set, is sent after the Voice LC Headers. */
	bool has_pi_header;
	dmrgo_pdu_pi_header_t pi_header;
	/* TalkerAlias, when not empty, is sent in the embedded LC of every other superframe, in TalkerAliasFormat. */
	char *talker_alias;
	size_t talker_alias_len;
	/* TalkerAliasFormat is the character format of TalkerAlias. The zero value is DMRGO_LAYER3_TALKER_ALIAS_SEVEN_BIT. */
	dmrgo_layer3_talker_alias_data_format_t talker_alias_format;
	/* GPS, when set, is sent in the embedded LC of every other superframe, after the talker alias. */
	bool has_gps;
	dmrgo_pdu_flc_gps_info_t gps;
	/* InCall reports that the radio is party to the call on the channel, or that the call is a response that the channel solicited. Such a call starts whatever the channel state and dmrgo_voice_transmitter_config_t.access. (ETSI TS 102 361-1 clauses 5.2.1.6 and 5.2.2.2.7) */
	bool in_call;
	/* HangTime reports that the BS sends call or channel hang time bursts. With dmrgo_voice_transmitter_config_t.chan_auth set, a call that is not impolite then starts with the channel authorization. (ETSI TS 102 361-2 clause 5.1.1.6) */
	bool hang_time;
};

struct dmrgo_voice_frame_quality_t {
	/* ErrorsCorrected is the number of bit errors that the Golay codes corrected, at most 255. */
	uint8_t errors_corrected;
	/* Bad reports that section A of the frame was uncorrectable. */
	bool bad;
};

struct dmrgo_voice_stats_t {
	/* Bursts is the number of voice bursts of the call. */
	uint32_t bursts;
	/* Lost is the number of voice bursts that did not arrive. */
	uint32_t lost;
	/* Duplicates is the number of bursts dropped as copies of an earlier one, voice bursts and Voice LC Headers. */
	uint32_t duplicates;
	/* Late is the number of voice bursts dropped because their sequence number was behind the last one. */
	uint32_t late;
	/* BitsChecked is the number of vocoder bits that the AMBE+2 FEC covered. */
	uint32_t bits_checked;
	/* BitErrors is the number of bit errors that the AMBE+2 FEC corrected. BitErrors / BitsChecked is the bit error rate, as dmrgo_fec_ber_calculator_t counts it. */
	uint32_t bit_errors;
	/* Duration is the time from the start of the call to its end. */
	dmrgo_duration_t duration;
};

struct dmrgo_voice_event_t {
	/* Kind is the kind of the event. */
	dmrgo_voice_event_kind_t kind;
	/* Call is the call the event belongs to. For voice before the LC is known, its Origin is DMRGO_VOICE_ORIGIN_UNKNOWN. */
	dmrgo_voice_call_t call;
	/* Position is the superframe position of a voice burst, or DMRGO_ENUMS_VOICE_BURST_UNKNOWN when no evidence placed it. */
	dmrgo_enums_voice_burst_type_t position;
	/* Burst is the voice burst or the PI Header as received. */
	dmrgo_layer2_raw_burst_t burst;
	/* Frames is the FEC result of each vocoder slot of a voice burst. */
	dmrgo_voice_frame_quality_t frames[3];
	/* Lost is the number of voice bursts lost just before this one, at most 255. For the first voice burst after a Voice LC Header or PI Header, it is the number lost after the header. */
	uint8_t lost;
	/* LC is the embedded LC of a DMRGO_VOICE_EVENT_EMBEDDED. */
	dmrgo_pdu_full_link_control_t lc;
	/* Text is the alias of a DMRGO_VOICE_EVENT_TALKER_ALIAS, in UTF-8, at most DMRGO_PDU_TALKER_ALIAS_MAX_TEXT bytes. */
	uint8_t *text;
	size_t text_len;
	/* Reason is why the call ended. */
	dmrgo_voice_end_reason_t reason;
	/* Stats counts what the Receiver saw during the call. */
	dmrgo_voice_stats_t stats;
};

struct dmrgo_voice_output_t {
	/* Kind is the kind of the output. */
	dmrgo_voice_output_kind_t kind;
	/* Burst is the burst to send. */
	dmrgo_layer2_raw_burst_t burst;
	/* Due is the time at which the burst goes on air, 60 ms after the one before it. */
	dmrgo_duration_t due;
	/* Hint is what the burst is, for a transport: DMRGO_LAYER2_KIND_VOICE with the superframe position, or DMRGO_LAYER2_KIND_DATA with the data type of a header, PI Header or terminator, or DMRGO_LAYER2_KIND_REVERSE_CHANNEL. Its Slot is the Slot of the config. */
	dmrgo_layer2_hint_t hint;
	/* Fill reports a voice burst with a fill in place of voice that was not queued in time, or with silence that pads the last superframe. The fills that Relay queues for bursts that the Receiver reports lost are voice and do not set it. */
	bool fill;
	/* Reason is why the transmission ended: DMRGO_VOICE_END_TERMINATOR after a normal end, DMRGO_VOICE_END_LOST for a relayed call that was lost, DMRGO_VOICE_END_TIMEOUT after T_TO. */
	dmrgo_voice_end_reason_t reason;
};

struct dmrgo_voice_interrupter_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* ColorCode is the color code of the EMB of the standalone RC bursts. The EMB also has PI set, as an RC for the other logical channel. (ETSI TS 102 361-1 clause 6.4.2 and Table 9.19, ETSI TS 102 361-2 clause 6.3.5) */
	dmrgo_enums_color_code_t color_code;
	/* Wait is T_RCtimer, the wait for the Terminator with LC after each try. 0 means DMRGO_CONSTANTS_TRC_TIMER (600 ms), and a negative value waits until the terminator or Cancel. (ETSI TS 102 361-2 clause A.1) */
	dmrgo_duration_t wait;
	/* Retries is the number of tries after the first. 0 means 1, the one automatic retry of Motorola Transmit Interrupt (MOTOTRBO System Planner 2.3.2), a negative value means none, and it is at most DMRGO_VOICE_MAX_RETRIES. (ETSI TS 102 361-2 clause 6.3.5) */
	int64_t retries;
	/* Repeats is the number of standalone RC bursts of each try, 60 ms apart. 0 means 1; at most DMRGO_VOICE_MAX_REPEATS. (ETSI TS 102 361-2 clause 6.3.5) */
	int64_t repeats;
	/* Scratch, when set, is the Burst that Burst decodes into. Machines that run on one thread can share one. NULL means the Interrupter makes its own. (ETSI TS 102 361-2 clause 6.3.5) */
	dmrgo_layer2_burst_t *scratch;
	/* Slot is the TDMA slot of the machine, which it puts in the Hint of each burst it sends. DMRGO_ENUMS_SLOT_UNKNOWN leaves it unknown. */
	dmrgo_enums_slot_t slot;
	/* Lead makes Tick emit a burst this long before its Due time, so that an RF FIFO can be filled ahead. 0 means at Due; it must not be negative. T_RCtimer counts from the Due times. */
	dmrgo_duration_t lead;
};

struct dmrgo_voice_jitter_packet_t {
	/* Burst is the burst of the packet. HasBurst reports whether it is set. */
	dmrgo_layer2_raw_burst_t burst;
	/* HasBurst is false for a transport frame without a burst, that Push took with a NULL raw. */
	bool has_burst;
	/* Hint is the Hint that Push took, with At set to Due. */
	dmrgo_layer2_hint_t hint;
	/* Source is the src that Push took. */
	uint32_t source;
	/* Due is the time at which the packet plays: the caller hands it to a Receiver or a Repeater with this time as now. */
	dmrgo_duration_t due;
};

struct dmrgo_voice_jitter_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* Delay is the playout delay: the time from the arrival of the packet that came first for its place in the stream to the Pop that returns it. A packet that comes up to Delay later than that, in any order, plays in its place. 0 means DMRGO_VOICE_DEFAULT_JITTER, and a negative value turns the buffer off: Push then returns DMRGO_VOICE_JITTER_BYPASS for every packet. At most DMRGO_VOICE_MAX_JITTER. */
	dmrgo_duration_t delay;
	/* Lead is the time from a Pop to the Due time of the packet it returns, for a Transmitter that relays the call with this dmrgo_voice_transmitter_config_t.lead, so that the packet is there before the Transmitter sends its burst. It must not be negative. */
	dmrgo_duration_t lead;
};

struct dmrgo_voice_receiver_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* ColorCode, when set, drops bursts with another color code, except a voice burst of a call that the transport does not place whose EMB is within 5 bits of a codeword of ColorCode, which goes to the sync check of the package doc. Burst A carries no color code, so it does not start a late entry. has_color_code false accepts every color code. */
	bool has_color_code;
	dmrgo_enums_color_code_t color_code;
	/* Lost is the time without a burst after which a call ends with DMRGO_VOICE_END_LOST. 0 means DMRGO_VOICE_DEFAULT_LOST, and a negative value turns the timer off. */
	dmrgo_duration_t lost;
	/* Hang is the call hang time, in which a call to the same target continues the session. 0 means DMRGO_CONSTANTS_T_CALL_HANG (3 s), and a negative value turns session tracking off. A broadcast call and a call to DMRGO_CONSTANTS_ALL_MSID have no hang time (ETSI TS 102 361-2 clause 5.3.2.3.2). */
	dmrgo_duration_t hang;
	/* Scratch, when set, is the Burst that Burst decodes into. Receivers that run on one thread can share one, because a Receiver is done with it when its method returns. Make it with dmrgo_layer2_new_burst, so that no decode allocates. NULL means the Receiver makes its own. */
	dmrgo_layer2_burst_t *scratch;
};

struct dmrgo_voice_transmitter_config_t {
	/* size is sizeof the struct, which the caller sets: the library reads only the members that it covers, as zero for the rest. */
	size_t size;
	/* ColorCode is the color code of the slot types and EMBs. */
	dmrgo_enums_color_code_t color_code;
	/* Source selects the SYNC patterns: DMRGO_LAYER2_SYNC_SOURCE_BS, the zero value, for a repeater outbound, DMRGO_LAYER2_SYNC_SOURCE_MS for a radio. */
	dmrgo_layer2_sync_source_t source;
	/* Silence is the 72-bit slot that fills a burst when no voice is queued, and pads the last superframe, packed as dmrgo_layer2_raw_burst_voice_slots returns it. The zero value means dmrgo_vocoder_ambe_silence_slot(). A Codec2 caller sets its own. A relayed call with a FID other than DMRGO_ENUMS_FID_STANDARDIZED and DMRGO_ENUMS_FID_MOTOROLA, such as a Codec2 call, repeats its last vocoder slot in place of Silence once it has one, as MMDVMHost does, because the silence of one codec is noise to another. */
	uint8_t silence[9];
	/* Headers is the number of Voice LC Headers before burst A. 0 means 1, as ETSI TS 102 361-1 clause 5.1.2.2 gives; at most DMRGO_VOICE_MAX_HEADERS. MMDVMHost sends 3 as a duplex repeater. */
	int64_t headers;
	/* Terminators is the number of Terminators with LC at the end of a call. 0 means 1; at most DMRGO_VOICE_MAX_TERMINATORS. */
	int64_t terminators;
	/* Timeout is the transmit timeout T_TO. 0 means DMRGO_CONSTANTS_TTO (180 s), and a negative value turns it off (ETSI TS 102 361-2 clause 6.1). */
	dmrgo_duration_t timeout;
	/* Queue is the number of vocoder slots buffered. 0 means Headers+2 bursts, DMRGO_VOICE_DEFAULT_QUEUE for 0 or 1 Headers; at most DMRGO_VOICE_MAX_QUEUE. It must hold Headers+1 bursts, so that a relayed late entry can send its headers first. */
	int64_t queue;
	/* Lead makes Tick emit a burst this long before its Due time, so that an RF FIFO can be filled ahead. 0 means at Due; it must not be negative. */
	dmrgo_duration_t lead;
	/* Access is the channel access policy of Start. A polite call waits up to IdleSearch for Channel to report an idle channel and ends with DMRGO_VOICE_END_DENIED when it does not; an impolite call starts at once. Relay ignores it. The zero value is polite to own color code. (ETSI TS 102 361-1 clauses 5.2.1.6 and 5.2.2) */
	dmrgo_enums_access_t access;
	/* IdleSearch is T_IdleSrch, the wait for an idle channel before a polite call. 0 means DMRGO_VOICE_DEFAULT_IDLE_SEARCH, and a negative value denies the call at once. (ETSI TS 102 361-1 clause 5.2.2.2.5) */
	dmrgo_duration_t idle_search;
	/* Interruptible makes Interrupt end the call on a Cease Transmission Request. A Cease Transmission Command ends it whatever this says. (ETSI TS 102 361-2 clauses 6.3.3 and 6.3.4) */
	bool interruptible;
	/* ChanAuth is T_MS_ChanAuth, the wait for the BS to repeat the ChanAuth PDU of a call that starts in hang time, dmrgo_voice_call_options_t.hang_time. 0 means no channel authorization; DMRGO_CONSTANTS_TMS_CHAN_AUTH and DMRGO_CONSTANTS_TMS_CHAN_AUTH_MULTI_SITE are the recommended values. (ETSI TS 102 361-2 clause 5.1.1.6.2) */
	dmrgo_duration_t chan_auth;
	/* HoldoffMax is the upper end of the random holdoff before a new channel authorization try. 0 means DMRGO_VOICE_DEFAULT_HOLDOFF_MAX, and a negative value means no holdoff. (ETSI TS 102 361-2 clause 5.1.1.6.2) */
	dmrgo_duration_t holdoff_max;
	/* Seed seeds the generator of the random holdoff, so that the same inputs give the same outputs. (ETSI TS 102 361-2 clause 5.1.1.6.2) */
	uint64_t seed;
	/* Scratch, when set, is the Burst that Burst decodes into. Machines that run on one thread can share one. NULL means the Transmitter makes its own when ChanAuth is set. (ETSI TS 102 361-2 clause 5.1.1.6.2) */
	dmrgo_layer2_burst_t *scratch;
	/* Slot is the TDMA slot of the machine, which it puts in the Hint of each burst it sends. DMRGO_ENUMS_SLOT_UNKNOWN leaves it unknown. */
	dmrgo_enums_slot_t slot;
};

