int dmrgo_layer2_voice_transmitter_add_slots(dmrgo_layer2_voice_transmitter_t *self, const uint8_t (*slots)[9], size_t slots_len, dmrgo_layer2_raw_burst_t *out, size_t out_cap, size_t *out_len, size_t *out_need);
