int dmrgo_layer2_voice_transmitter_append_slots(dmrgo_layer2_voice_transmitter_t *self, dmrgo_layer2_raw_burst_t *dst, size_t dst_cap, size_t *dst_len, size_t *dst_need, const uint8_t (*slots)[9], size_t slots_len);
/* dmrgo_layer2_voice_transmitter_append_terminate_need sets *items and *arena to the room that dmrgo_layer2_voice_transmitter_append_terminate needs for these arguments, without a change to the handle. */
