int dmrgo_layer2_voice_transmitter_append_terminate(dmrgo_layer2_voice_transmitter_t *self, dmrgo_layer2_raw_burst_t *dst, size_t dst_cap, size_t *dst_len, size_t *dst_need);
/* Go: layer2.VoiceTransmitter.Header. Header returns the Voice LC Header burst, sent before the first voice burst. */
